 namespace Gordic.Pok.WebClient {

    @Decorators.gcontent
    export class GPokHromadnaKontrolaDatTab extends GContentBase {


        private gridKontrolaDataKnihy: JQuery<HTMLElement>;
        private gridKontrolaDatVysledek: JQuery<HTMLElement>;

        onContentReady() {

            this.setBreadcrumbs([{ caption: "Kontrola dat", defaultAction: true }]);
            var that = this;

            var wizard = new Gordic.Wizard();

            wizard.create(
                { content: that }
                , {
                    title: "Kontrola dat",
                    steps: [
                        {
                            caption: "Výběr kontrol",
                            create: function (cnt, contentDiv, change) {

                                var formDiv = $("<div>").appendTo(contentDiv);
                                let form = new Gordic.Forms
                                    .Form({
                                        name: "pokKontrolyForm", tabOptions: { title: "jres:31302279", opened: true }, layoutDescriptor: "L2M2S1"
                                    } as any)
                                    .addSection()                               
                                    .addField("gcheck", { name: "dvojiRezervace", label: "jres:31302280", initialValue: cnt["poleKontroly"] ? cnt["poleKontroly"][0] : true}) //RC 31302280 : Kontrola dvojí rezervace                                   
                                    .addField("gcheck", { name: "rezervacePohyby", label: "jres:31302281", initialValue: cnt["poleKontroly"] ? cnt["poleKontroly"][1] : true }) //RC 31302281 : Kontrola rezervačních pohybů                                  
                                    .addField("gcheck", { name: "ucetPohyby", label: "jres:31302282", initialValue: cnt["poleKontroly"] ? cnt["poleKontroly"][2] : true }) //RC 31302282 : Kontrola účetních pohybů                               
                                    .addField("gcheck", { name: "opravaVlastnika", label: "jres:31302283", initialValue: cnt["poleKontroly"] ? cnt["poleKontroly"][3] : true })  //RC 31302283 : Kontrola/Oprava vyplnění vlastníka                                   
                                    .addField("gcheck", { name: "opravaMeny", label: "jres:31302284", initialValue: cnt["poleKontroly"] ? cnt["poleKontroly"][4] : true })  //RC 31302284 : Kontrola/Oprava vyplnění měn                                  
                                    .addField("gcheck", { name: "priznakRezervace", label: "jres:31302285", initialValue: cnt["poleKontroly"] ? cnt["poleKontroly"][5] : true }) //RC 31302285 : Kontrola/Oprava příznaku rezervace                                   
                                    .addField("gcheck", { name: "soucetDokladu", label: "jres:31302286", initialValue: cnt["poleKontroly"] ? cnt["poleKontroly"][6] : true })  //RC 31302286 : Kontrola/Oprava součtu dokladu                                   
                                    .addSection()
                                    .addField("gcheck", { name: "zustatekKnihy", label: "jres:31302287", initialValue: cnt["poleKontroly"] ? cnt["poleKontroly"][7] : true }) //RC 31302287 : Kontrola/Oprava zůstatku knihy                                    
                                    .addField("gcheck", { name: "spisUzel", label: "jres:31302288", initialValue: cnt["poleKontroly"] ? cnt["poleKontroly"][8] : true }) //RC 31302288 : Kontrola/Oprava spisového uzlu                               
                                    .addField("gcheck", { name: "stavZauctovani", label: "jres:31302289", initialValue: cnt["poleKontroly"] ? cnt["poleKontroly"][9] : true })  //RC 31302289 : Kontrola/Oprava stavu zaúčtování
                                    .addField("gcheck", { name: "typPohledavky", label: "Kontrola typu pohledávky", initialValue: cnt["poleKontroly"] ? cnt["poleKontroly"][10] : true }) 
                                    .addField("gcheck", { name: "braniciUzaverce", label: "Doklady bránící uzávěrce", initialValue: cnt["poleKontroly"] ? cnt["poleKontroly"][11] : true }) 
                                    .addField("gcheck", { name: "schvaleneNeevidovane", label: "Kontrola/Oprava schválených neevidovaných", initialValue: cnt["poleKontroly"] ? cnt["poleKontroly"][12] : true }) 
                                    .addField("gbutton", "", {
                                        params: {
                                            action: new GAction({
                                                caption: "+/-",
                                                customClass: "",
                                                name: 'actTest2', run: (ev, ctx) => {

                                                    cnt["poleKontroly"] = [];

                                                    cnt["poleKontroly"][0] = cnt.findFields("dvojiRezervace").gfield("getValue");
                                                    cnt["poleKontroly"][1] = cnt.findFields("rezervacePohyby").gfield("getValue");
                                                    cnt["poleKontroly"][2] = cnt.findFields("ucetPohyby").gfield("getValue");
                                                    cnt["poleKontroly"][3] = cnt.findFields("opravaVlastnika").gfield("getValue");
                                                    cnt["poleKontroly"][4] = cnt.findFields("opravaMeny").gfield("getValue");
                                                    cnt["poleKontroly"][5] = cnt.findFields("priznakRezervace").gfield("getValue");
                                                    cnt["poleKontroly"][6] = cnt.findFields("soucetDokladu").gfield("getValue");
                                                    cnt["poleKontroly"][7] = cnt.findFields("zustatekKnihy").gfield("getValue");
                                                    cnt["poleKontroly"][8] = cnt.findFields("spisUzel").gfield("getValue");
                                                    cnt["poleKontroly"][9] = cnt.findFields("stavZauctovani").gfield("getValue");
                                                    cnt["poleKontroly"][10] = cnt.findFields("typPohledavky").gfield("getValue");
                                                    cnt["poleKontroly"][11] = cnt.findFields("braniciUzaverce").gfield("getValue");
                                                    cnt["poleKontroly"][12] = cnt.findFields("schvaleneNeevidovane").gfield("getValue");

                                                    let checkTrue = cnt["poleKontroly"].filter(x => x == true);
                                                    let checkFalse = cnt["poleKontroly"].filter(x => x == false);

                                                    let checkValue = true;
                                                    if (checkTrue.length == 0)
                                                        checkValue = true;
                                                    else if (checkFalse == 0)
                                                        checkValue = false;
                                                    else if (checkTrue.length < checkFalse.length)
                                                    checkValue = false;


                                                    cnt.findFields("dvojiRezervace,rezervacePohyby,ucetPohyby,opravaVlastnika,opravaMeny,priznakRezervace,soucetDokladu,zustatekKnihy,spisUzel,stavZauctovani,typPohledavky,braniciUzaverce,schvaleneNeevidovane").gfield("setValue", checkValue);
                                                   
                                                   
                                                }
                                            })
                                        }
                                    });

                                formDiv.gform("createFrom", form);
                             
                            },
                            change: function (cnt, $element, ctx) { // event na změnu kroku
                              
                               // pole s kontrolami
                                cnt["poleKontroly"] = [];

                                cnt["poleKontroly"][0] = cnt.findFields("dvojiRezervace").gfield("getValue");
                                cnt["poleKontroly"][1] = cnt.findFields("rezervacePohyby").gfield("getValue");
                                cnt["poleKontroly"][2] = cnt.findFields("ucetPohyby").gfield("getValue");
                                cnt["poleKontroly"][3] = cnt.findFields("opravaVlastnika").gfield("getValue");
                                cnt["poleKontroly"][4] = cnt.findFields("opravaMeny").gfield("getValue");
                                cnt["poleKontroly"][5] = cnt.findFields("priznakRezervace").gfield("getValue");
                                cnt["poleKontroly"][6] = cnt.findFields("soucetDokladu").gfield("getValue");
                                cnt["poleKontroly"][7] = cnt.findFields("zustatekKnihy").gfield("getValue");
                                cnt["poleKontroly"][8] = cnt.findFields("spisUzel").gfield("getValue");
                                cnt["poleKontroly"][9] = cnt.findFields("stavZauctovani").gfield("getValue");
                                cnt["poleKontroly"][10] = cnt.findFields("typPohledavky").gfield("getValue");
                                cnt["poleKontroly"][11] = cnt.findFields("braniciUzaverce").gfield("getValue");
                                cnt["poleKontroly"][12] = cnt.findFields("schvaleneNeevidovane").gfield("getValue");

                                let checkTrue = cnt["poleKontroly"].filter(x => x == true);
                                if (checkTrue.length == 0) {
                                    ctx.stepsEnable[1] = false;
                                }
                                else {
                                    ctx.stepsEnable[1] = true;
                                }
                                
                               
                            }

                        },
                        {
                            caption: "Výběr knih",
                            create: function (cnt, contentDiv, change) {

                                var gf = new Gordic.Data.GridFormat();
                                gf.addTextColumn({
                                    name: "nazev",
                                    caption: "Název knihy", //RC 31302005 : PID
                                    sortable: false
                                })
                                    .addTextColumn({
                                        name: "zkratka",
                                        caption: "Zkratka",
                                        sortable: false,
                                        width: 300
                                    }),


                                    Gordic.Isl.PokKniha.list(rq => {
                                        return {
                                            filters: {
                                                ico: that.gpc.ico,
                                                rok: that.gpc.rok,
                                                faze: that.gpc.faze,
                                                aktivita: [100, 300]
                                            }
                                        }
                                    })
                                        .get()
                                        .done(function (data) {

                                            that.gridKontrolaDataKnihy = $("<div>")
                                                .appendTo(contentDiv)
                                                .gautofit()
                                                .ggrid<Gordic.Hpl.Interface.GPokKnihaDto>({
                                                    columnMode: "fit",     // fit (defaultne by melo byt toto), full
                                                    columns: gf,
                                                    multi: true,
                                                    defaultAction: new GAction({     //obsluzna akce, ktera se spousti dbl clickem nad radkem
                                                        name: "gridRowSelectedActStep0",
                                                        run: function (ev, ctx) {
                                                            //_this.actions.actContinue.run();
                                                        }
                                                    }),
                                                    data: data.data
                                                });

                                        });

                            },
                            change: function (cnt, $element, ctx) { // event na změnu kroku

                                //knihy
                                cnt["dataKontrolaDataKnihy"] = that.gridKontrolaDataKnihy.ggrid("getSelection");
                            }

                        },
                        {
                            caption: "Výsledek",
                            create: function (cnt, contentDiv, change) {

                                var gridFormat = new Gordic.Data.GridFormat<GPokUniverzalniDto>();

                                gridFormat.addTextColumn({ name: "column2", caption: "Název knihy" })
                                    .addTextColumn({ name: "column5", caption: "Zkratka" })
                                    .addTextColumn({ name: "column1", caption: "jres:31302278" });//RC 31302278 : Kontrola
                                    

                                that.gridKontrolaDatVysledek = $("<div>").appendTo(contentDiv)
                                    .gautofit()
                                    .ggrid({
                                        data: [],
                                        renderMode: "auto",     // auto, all-at-once, paged-sync, paged-async
                                        columnMode: "fit",      // fit, full
                                        navigationMode: "row",  // row, cell                                       
                                        rowNumbers: false,
                                        columns: gridFormat,
                                        defaultAction: new GAction({     //obsluzna akce, ktera se spousti dbl clickem nad radkem
                                            name: "gridRowSelectedActStep0",
                                            run: function (ev, ctx) {
                                                var row = ctx.cellInfo.data;
                                                that.dialogs.messageBox("Výsledek kontroly dat", row.column3, [GDlg.mbbOk],"",800,200); //pouze oK a ne YES/NO
                                            }
                                        }),
                                    });

                                var data = cnt["dataKontrolaDataKnihy"];
                                let kontroly = cnt["poleKontroly"];

                                cnt.beginOperation("Probíhá kontrola dat..");
                                let counter = 0;

                                data.forEach(function (row) {
                                    that.hromadnaKontrolaOne(row, kontroly)
                                        .always(function () {

                                            counter = counter + 1;

                                            if (counter == data.length) {
                                                cnt.endOperation();

                                            }
                                        })

                                });                              

                            },
                            change: function (cnt, $element, ctx) { // event na změnu kroku

                            }

                        }
                    ],
                    complete: function (gcontent, contentDiv, change) {
                        gcontent.tryClose();
                    }
                });
        }

        private hromadnaKontrolaOne(rowKnihy: Gordic.Hpl.Interface.GPokKnihaDto, kontroly: boolean[]): JQueryPromise<void> {

            var that = this;

            var def = $.Deferred();

            this.call("SpustitKontroluVybrane",
                {
                    ixpDen: rowKnihy.ixp_den,
                    kontorlaRezervace: kontroly[0],
                    rezPohyb: kontroly[1],
                    ucetPohyb: kontroly[2],
                    vyplnVlastnika: kontroly[3],
                    vyplneniMen: kontroly[4],
                    prizRezervace: kontroly[5],
                    soucetDokladu: kontroly[5],
                    zustatekKnihy: kontroly[7],
                    spisUzel: kontroly[8],
                    stavZauctovani: kontroly[9],
                    typPohledavky: kontroly[10],
                    braniciUzaverce: kontroly[11],
                    schvaleneNeevidovane: kontroly[12]


                }).done(function (data: GPokUniverzalniDto) {

                    data.column2 = rowKnihy.nazev;
                    data.column5 = rowKnihy.zkratka;
                    that.gridKontrolaDatVysledek.ggrid("getView").updateData(data, "add");


                    def.resolve();


                })
                .fail(function (xhr, type, vobj) {

                    def.reject();
                });


        
            return def.promise();


        }

       

        }


        }

    
